4: export const DEPENDENCY_GRAPH_SKILL_NAME = 'vibeknowledge-dependency-graph';
5: export const QUERY_SKILL_NAME = 'vibeknowledge-query';
6: 
7: /** Installs the bundled project skill into the standard Agent Skills folder. */
8: export class AgentSkillService {
9:   private readonly sourceDirectory: string;
10: 
11:   constructor(extensionPath: string, private readonly skillName = DEPENDENCY_GRAPH_SKILL_NAME) {
12:     if (![DEPENDENCY_GRAPH_SKILL_NAME, QUERY_SKILL_NAME].includes(skillName)) {
13:       throw new Error(`Unknown bundled skill: ${skillName}`);
14:     }
15:     this.sourceDirectory = path.join(
16:       extensionPath,
17:       skillName === QUERY_SKILL_NAME ? 'dist' : 'resources',
18:       'skills',
19:       skillName
20:     );
21:   }
22: 
23:   public getInstallDirectory(workspaceRoot: string): string {
24:     return path.join(
25:       workspaceRoot,
26:       '.agents',
27:       'skills',
28:       this.skillName
29:     );
30:   }
31: 
32:   public getInstalledSkillPath(workspaceRoot: string): string {
33:     return path.join(this.getInstallDirectory(workspaceRoot), 'SKILL.md');
34:   }
35: 
36:   public isInstalled(workspaceRoot: string): boolean {
37:     return fs.existsSync(this.getInstallDirectory(workspaceRoot));
38:   }
39: 
40:   public install(workspaceRoot: string, overwrite = false): string {
41:     const sourceSkill = path.join(this.sourceDirectory, 'SKILL.md');
42:     if (!fs.existsSync(sourceSkill)) {
43:       throw new Error(`Bundled skill is missing: ${sourceSkill}`);
44:     }
45:     if (this.skillName === QUERY_SKILL_NAME && !fs.existsSync(path.join(this.sourceDirectory, 'scripts', 'query.cjs'))) {
46:       throw new Error('Bundled query runtime is missing. Rebuild the extension before installing the Skill.');
47:     }
48: 
49:     const targetDirectory = this.getInstallDirectory(workspaceRoot);
50:     if (this.isInstalled(workspaceRoot) && !overwrite) {
51:       throw new Error(`Skill is already installed: ${targetDirectory}`);
52:     }
53: 
54:     this.copyDirectory(this.sourceDirectory, targetDirectory, overwrite);
55:     return this.getInstalledSkillPath(workspaceRoot);
56:   }
57: 
58:   private copyDirectory(
59:     sourceDirectory: string,
60:     targetDirectory: string,
61:     overwrite: boolean
62:   ): void {
63:     fs.mkdirSync(targetDirectory, { recursive: true });
64: 
65:     for (const entry of fs.readdirSync(sourceDirectory, { withFileTypes: true })) {
66:       const sourcePath = path.join(sourceDirectory, entry.name);
67:       const targetPath = path.join(targetDirectory, entry.name);
68: 
69:       if (entry.isDirectory()) {
70:         this.copyDirectory(sourcePath, targetPath, overwrite);
71:         continue;
72:       }
73:       if (!entry.isFile()) {
74:         continue;
75:       }
76:       if (!overwrite && fs.existsSync(targetPath)) {
77:         throw new Error(`Skill file already exists: ${targetPath}`);
78:       }
79:       fs.copyFileSync(sourcePath, targetPath);
80:     }
81:   }
82: }
