17:   public notify(filePath: string): void {
18:     if (this.disposed) {
19:       return;
20:     }
21:     this.changedPaths.add(filePath);
22:     if (this.timer) {
23:       clearTimeout(this.timer);
24:     }
25:     this.timer = setTimeout(() => {
26:       this.timer = undefined;
27:       void this.flush();
28:     }, this.delayMs);
29:   }
30: 
31:   public flush(): Promise<void> {
32:     if (this.disposed || this.changedPaths.size === 0) {
33:       return this.running;
34:     }
35:     if (this.timer) {
36:       clearTimeout(this.timer);
37:       this.timer = undefined;
38:     }
39:     const paths = [...this.changedPaths].sort((left, right) =>
40:       left.localeCompare(right, 'en')
41:     );
42:     this.changedPaths.clear();
43:     this.running = this.running
44:       .catch(() => undefined)
45:       .then(() => this.callback(paths));
46:     return this.running;
47:   }
48: 
49:   public dispose(): void {
50:     this.disposed = true;
51:     this.changedPaths.clear();
52:     if (this.timer) {
53:       clearTimeout(this.timer);
54:       this.timer = undefined;
55:     }
56:   }
57: }
